import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source with kernel and C++ wrapper
cuda_src = r'''
#include <torch/types.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void mse_kernel(const scalar_t* __restrict__ pred,
                           const scalar_t* __restrict__ target,
                           float* __restrict__ out,
                           const int64_t N) {
    extern __shared__ float sdata[];
    const int tid = threadIdx.x;
    const int idx = blockIdx.x * blockDim.x + tid;
    float sum = 0.0f;
    // stride loop over the input
    for (int64_t i = idx; i < N; i += blockDim.x * gridDim.x) {
        const float p = __half2float(pred[i]);
        const float t = __half2float(target[i]);
        const float d = p - t;
        sum += d * d;
    }
    sdata[tid] = sum;
    __syncthreads();

    // reduction in shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // write block result to global accumulator
    if (tid == 0) {
        atomicAdd(out, sdata[0]);
    }
}

// C++ wrapper callable from Python
void mse_forward(torch::Tensor pred,
                 torch::Tensor target,
                 torch::Tensor out) {
    const int64_t N = pred.numel();
    const int threads = 256;
    const int blocks = std::min<int>((N + threads - 1) / threads, 1024);
    const int shared_mem = threads * sizeof(float);

    // launch kernel; tensors are half (fp16)
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(pred.scalar_type(), "mse_forward", ([&] {
        mse_kernel<<<blocks, threads, shared_mem>>>(
            pred.data_ptr<scalar_t>(),
            target.data_ptr<scalar_t>(),
            out.data_ptr<float>(),
            N);
    }));
    cudaGetLastError();
}
'''

# Compile the inline extension
mse_mod = load_inline(name='mse_extension',
                      cpp_sources='',
                      cuda_sources=cuda_src,
                      functions=['mse_forward'],
                      verbose=False)

# Python wrapper that uses the compiled kernel
def _mse_fp16(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    assert pred.is_cuda and target.is_cuda, "inputs must be CUDA tensors"
    assert pred.dtype == torch.float16 and target.dtype == torch.float16, "inputs must be fp16"
    assert pred.shape == target.shape, "shape mismatch"

    N = pred.numel()
    # accumulator in fp32
    acc = torch.zeros(1, dtype=torch.float32, device=pred.device)
    # launch kernel
    mse_mod.mse_forward(pred.contiguous(), target.contiguous(), acc)
    # compute mean and cast back to fp16
    mean_fp32 = acc / N
    return mean_fp32.to(torch.float16)

# Model definition matching the reference API
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        return _mse_fp16(predictions, targets)
